  static {
    __name(this, "AdminUserService");
  }
  async listUsers() {
    return await this.prisma.user.findMany({
      select: {
        id: true,
        email: true,
        roles: true,
        status: true,
        createdAt: true,
        clientProfile: { select: { fullName: true } },
        pswProfile: { select: { fullName: true, isApproved: true } }
      },
      orderBy: { createdAt: "desc" }
    });
  }
