r22.openapi(predictiveStaffingRoute, async (c) => {
  const prisma = c.get("prisma");
  try {
    const psws = await prisma.user.findMany({
      where: {
        roles: { hasSome: ["psw", "rn", "rmt", "rpt", "rch"] },
        status: "active"
      },
      include: {
        pswProfile: true,
        reportedIncidents: {
          where: {
            createdAt: {
              gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1e3)
              // Last 30 days
            }
          }
        }
      }
    });
    const fourteenDaysAgo = new Date(Date.now() - 14 * 24 * 60 * 60 * 1e3);
    const timesheets = await prisma.timesheet.findMany({
      where: {
        createdAt: {
          gte: fourteenDaysAgo
        }
      },
      include: {
        items: true
      }
    });
    const riskScores = psws.map((psw2) => {
      let score = 0;
      let riskFactors = [];
      const pswTimesheets = timesheets.filter((t) => t.pswId === psw2.pswProfile?.id);
      let totalMinutes = 0;
      pswTimesheets.forEach((ts) => {
        ts.items.forEach((item) => totalMinutes += item.minutes);
      });
      const totalHours = totalMinutes;
      if (totalHours > 80) {
        score += 40;
        riskFactors.push(`High hours (${totalHours.toFixed(1)}h in last 14 days)`);
      } else if (totalHours > 60) {
        score += 20;
        riskFactors.push("Elevated hours");
      }
      const incidentCount = psw2.reportedIncidents.length;
      if (incidentCount > 2) {
        score += 30;
        riskFactors.push(`Multiple recent incidents reported (${incidentCount})`);
      } else if (incidentCount > 0) {
        score += 15;
        riskFactors.push("Recent incident reported");
      }
      if (score === 0 && totalHours > 0 && totalHours <= 40) {
        score -= 10;
      }
      return {
        userId: psw2.id,
        pswId: psw2.pswProfile?.id,
        name: psw2.pswProfile?.fullName || psw2.email,
        score: Math.max(0, Math.min(score, 100)),
        // Cap between 0 and 100
        riskLevel: score >= 70 ? "High" : score >= 40 ? "Medium" : "Low",
        riskFactors,
        totalHours14d: totalHours
      };
    });
    riskScores.sort((a, b2) => b2.score - a.score);
    return c.json({ data: riskScores }, 200);
  } catch (error3) {
    console.error("Error calculating predictive staffing:", error3);
    return c.json({ data: [], error: "Internal server error" }, 500);
  }
});

