r25.openapi(provisionChildTenantRoute, async (c) => {
  const prisma = c.get("prisma");
  const user2 = c.get("user");
  const { name: name2, slug, adminEmail, adminPassword } = c.req.valid("json");
  if (!user2 || !user2.tenantId) {
    return c.json({ error: "Unauthorized" }, 401);
  }
  try {
    const existingTenant = await prisma.tenant.findUnique({ where: { slug } });
    if (existingTenant) {
      return c.json({ error: "Tenant slug already exists." }, 400);
    }
    const existingUser = await prisma.user.findUnique({ where: { email: adminEmail } });
    if (existingUser) {
      return c.json({ error: "Admin email already exists in the system." }, 400);
    }
    const mockHash = `hash_${adminPassword}`;
    const result = await prisma.$transaction(async (tx) => {
      const newTenant = await tx.tenant.create({
        data: {
          name: name2,
          slug,
          parentTenantId: user2.tenantId,
          // Link to parent
          status: "active"
        }
      });
      const newAdmin = await tx.user.create({
        data: {
          email: adminEmail,
          passwordHash: mockHash,
          tenantId: newTenant.id,
          roles: ["admin"]
          // Set as admin for their new tenant
        }
      });
      return { newTenant, newAdmin };
    });
    return c.json({
      id: result.newTenant.id,
      name: result.newTenant.name,
      slug: result.newTenant.slug,
      adminUserId: result.newAdmin.id
    }, 200);
  } catch (error3) {
    console.error("Error provisioning child tenant:", error3);
    return c.json({ error: "Failed" }, 500);
  }
});

