r26.post("/seed", async (c) => {
  const prisma = c.get("prisma");
  const { ContentRegistry: ContentRegistry4 } = web_admin_exports;
  const entries = flattenObject(ContentRegistry4);
  let created = 0, skipped = 0, errors = 0;
  for (const entry of entries) {
    const section = detectSection(entry.key);
    try {
      await prisma.registry.upsert({
        where: { key_tenantId: { key: entry.key, tenantId: null } },
        update: { value: entry.value, section, category: "content" },
        create: {
          key: entry.key,
          value: entry.value,
          category: "content",
          section
        }
      });
      created++;
    } catch (e) {
      try {
        const existing = await prisma.registry.findFirst({
          where: { key: entry.key, tenantId: null }
        });
        if (existing) {
          await prisma.registry.update({
            where: { id: existing.id },
            data: { value: entry.value, section, category: "content" }
          });
          created++;
        } else {
          await prisma.registry.create({
            data: {
              key: entry.key,
              value: entry.value,
              category: "content",
              section
            }
          });
          created++;
        }
      } catch {
        errors++;
      }
    }
  }
  return c.json({
    success: true,
    total: entries.length,
    created,
    skipped,
    errors,
    sampleKeys: entries.slice(0, 10).map((e) => e.key)
  });
});
