r56.openapi(getClientStatsRoute, async (c) => {
  const prisma = c.get("prisma");
  const userId = c.get("jwtPayload").sub;
  const profile3 = await prisma.clientProfile.findUnique({ where: { userId } });
  if (!profile3) return c.json({ error: "Profile not found" }, 404);
  const [invoices, entries, visits] = await Promise.all([
    prisma.invoice.findMany({
      where: { clientId: profile3.id, status: "paid" },
      select: { total: true }
    }),
    prisma.dailyEntry.findMany({
      where: { clientId: profile3.id },
      orderBy: { createdAt: "desc" },
      take: 7,
      select: { createdAt: true, mood: true }
    }),
    prisma.visit.findMany({
      where: { clientId: profile3.id, status: "completed" },
      include: { psw: { select: { id: true, fullName: true } } },
      take: 50
    })
  ]);
  const totalBudget = 5e3;
  const usedBudget = invoices.reduce((acc, inv) => acc + (Number(inv.total) || 0), 0);
  const spendingData = [
    { name: "Used", value: usedBudget },
    { name: "Remaining", value: Math.max(0, totalBudget - usedBudget) }
  ];
  const wellnessData = entries.reverse().map((e) => ({
    day: new Date(e.createdAt).toLocaleDateString("en-US", { weekday: "short" }),
    mood: e.mood || 0,
    energy: Math.floor(Math.random() * 3) + (e.mood ? e.mood - 1 : 5)
  }));
  const pswCounts = {};
  visits.forEach((v) => {
    if (v.psw?.id) pswCounts[v.psw.id] = (pswCounts[v.psw.id] || 0) + 1;
  });
  const totalVisits = visits.length || 1;
  const primaryCount = Object.values(pswCounts).reduce((acc, count3) => acc + (count3 / totalVisits >= 0.3 ? count3 : 0), 0);
  const continuityData = [
    { name: "Primary Caregivers", value: Math.round(primaryCount / totalVisits * 100) },
    { name: "Relief Staff", value: Math.round((totalVisits - primaryCount) / totalVisits * 100) }
  ];
  return c.json({
    budget: spendingData,
    wellness: wellnessData.length > 0 ? wellnessData : [{ day: "N/A", mood: 0, energy: 0 }],
    continuity: continuityData
  }, 200);
});
