var engagement = new OpenAPIHono();
engagement.openapi(
  createRoute({
    ...ROUTE_METADATA.CLIENT.FAMILY_FEED,
    method: "get",
    path: "/feed",
    responses: {
      200: {
        description: "Success",
        content: {
          "application/json": {
            schema: z.object({
              notifications: z.array(z.any()),
              visits: z.array(z.any())
            })
          }
        }
      },
      404: {
        description: "Profile not found",
        content: {
          "application/json": {
            schema: z.object({
              error: z.string()
            })
          }
        }
      }
    }
  }),
  async (c) => {
    const prisma = c.get("prisma");
    const jwt2 = c.get("jwtPayload");
    const userId = jwt2.sub;
    const tenantId = jwt2.tenantId;
    const clientProfile = await prisma.clientProfile.findUnique({
      where: { userId }
    });
    if (!clientProfile) {
      return c.json({ error: "Client profile not found" }, 404);
    }
    const [notifications, visits] = await Promise.all([
      prisma.familyNotification.findMany({
        where: { clientId: clientProfile.id, tenantId },
        orderBy: { createdAt: "desc" },
        take: 20
      }),
      prisma.visit.findMany({
        where: { clientId: clientProfile.id, tenantId },
        include: {
          psw: { select: { fullName: true, avatarUrl: true } },
          service: { select: { name: true } }
        },
        orderBy: { requestedStartAt: "desc" },
        take: 10
      })
    ]);
    const events = [
      ...notifications.map((n) => ({
        id: n.id,
        type: n.type,
        message: n.message,
        createdAt: n.createdAt,
        category: "notification"
      })),
      ...visits.map((v) => ({
        id: v.id,
        type: v.status === "completed" ? "VISIT_COMPLETE" : "VISIT_ACTIVE",
        message: `${v.service.name} visit ${v.status === "completed" ? "completed" : "underway"} by ${v.psw?.fullName || "Caregiver"}`,
        createdAt: v.status === "completed" ? v.actualEndAt || v.createdAt : v.actualStartAt || v.createdAt,
        category: "visit",
        psw: v.psw
      }))
    ].sort((a, b2) => new Date(b2.createdAt).getTime() - new Date(a.createdAt).getTime());
    return c.json({ feed: events.slice(0, 30), notifications, visits }, 200);
  }
);
